from fractions import Fraction
def s(i,j,n):
    cnt=0
    for b in range(n//j+1):
        rem=n-b*j
        if rem%i==0: cnt+=1
    return cnt
def detfrac(M):
    n=len(M); D=Fraction(1); M=[row[:] for row in M]
    for c in range(n):
        piv=None
        for r in range(c,n):
            if M[r][c]!=0: piv=r;break
        if piv is None: return Fraction(0)
        if piv!=c: M[c],M[piv]=M[piv],M[c]; D=-D
        D*=M[c][c]
        for r in range(c+1,n):
            f=M[r][c]/M[c][c]
            for k in range(c,n): M[r][k]-=f*M[c][k]
    return D
for n in range(1,21):
